import{_ as e,o as a,c as l,a5 as r}from"./chunks/framework.CXvGqWf0.js";const k=JSON.parse('{"title":"漫画 · 第 24 话 现代颜色：oklch / color-mix / light-dark 设计系统的颜色革命","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.24-modern-colors.md","filePath":"comics/css/EP.24-modern-colors.md","lastUpdated":1793421609000}'),c={name:"comics/css/EP.24-modern-colors.md"};function i(d,o,t,s,h,n){return a(),l("div",null,[...o[0]||(o[0]=[r('<h1 id="漫画-·-第-24-话-现代颜色-oklch-color-mix-light-dark-设计系统的颜色革命" tabindex="-1">漫画 · 第 24 话 现代颜色：oklch / color-mix / light-dark 设计系统的颜色革命 <a class="header-anchor" href="#漫画-·-第-24-话-现代颜色-oklch-color-mix-light-dark-设计系统的颜色革命" aria-label="Permalink to &quot;漫画 · 第 24 话 现代颜色：oklch / color-mix / light-dark 设计系统的颜色革命&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/14-modern-colors">docs/css/14-modern-colors.md</a> ｜ 原画：<a href="./EP.24-modern-colors.svg">EP.24-modern-colors.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。被 180+ 硬编码 hex 色 token 折磨——品牌色微调一次，9 级色板逐行重算，暗色模式还要再翻一倍。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 CSS Color Level 4/5 三件套：oklch 感知均匀、color-mix 精确混色、light-dark 一行双主题。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>渐变章（EP.08）讲过多色过渡的视觉魔法，但底层颜色系统仍是 sRGB 时代的产物。像素酱先被 HSL 的感知不均匀折磨——同 L=50% 的黄和蓝，视觉亮度天差地别；再被手动维护的双份色板压垮。标签君引入现代颜色三件套：oklch 用感知均匀的 L/C/H 定义颜色，color-mix 在 oklch 空间混色告别灰暗中间色，light-dark 一行代码终结双份变量。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>HSL 亮度陷阱：<code>hsl(60, 100%, 50%)</code> 纯黄远比 <code>hsl(240, 100%, 50%)</code> 纯蓝看起来更亮，但 L 参数都是 50%。手动挑色板：<code>--blue-50: #eff6ff</code> 到 <code>--blue-900</code>，180+ token 硬编码。暗色模式双份：每个变量都要配一个 <code>-dark</code> 后缀。品牌色 <code>#3b82f6</code> 换成 <code>#7c3aed</code>，全盘重算。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三把新钥匙并排亮相：</p><ul><li><strong>oklch()</strong>：L（明度 0-100%）C（色度）H（色相 0-360°），Oklab 感知均匀空间，调 L 不发灰、不偏色。</li><li><strong>color-mix()</strong>：<code>color-mix(in oklch, A 60%, B)</code>，在感知空间中线性插值，避免 sRGB 混色的灰暗中间色。</li><li><strong>light-dark()</strong>：<code>light-dark(light-color, dark-color)</code>，配合 <code>color-scheme: light dark</code> 一行替代媒体查询。</li></ul><p>示例代码：<code>oklch(65% 0.22 265)</code> 定义主色，<code>oklch(from var(--brand) calc(l+0.1) c h)</code> 自动推导 hover 态。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四区落地：</p><ul><li><strong>色板生成</strong>：只定义 <code>--brand: oklch(58% 0.24 265)</code>，50-900 级通过调 L 和 C 比例自动生成；换品牌色只改 hue。</li><li><strong>双主题</strong>：<code>light-dark(oklch(99% 0.01 265), oklch(16% 0.03 265))</code> 无媒体查询、无变量翻倍，系统切换外观 CSS 自动跟随。</li><li><strong>状态推导</strong>：hover/active/disabled 全部由相对颜色语法 <code>calc(l±x)</code> 自动级联。</li><li><strong>兼容性</strong>：Chrome 111+ / Safari 15.4+ / Firefox 128+，旧浏览器用 postcss-preset-env 降级为 rgb/hex。</li></ul><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>oklch 感知均匀：同 L 值的不同色相视觉亮度一致，设计系统色板不再凭感觉。</li><li>color-mix 在 oklch 空间混色：避免 sRGB 线性插值的灰暗中间色。</li><li>light-dark() 需配合 color-scheme 声明，一行代码替代整段媒体查询。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：<code>oklch(60% 0.25 0deg)</code> 和 <code>oklch(60% 0.25 240deg)</code> 的视觉亮度一致吗？为什么 HSL 做不到这一点？</p><p><strong>答</strong>：一致。Oklch 基于 Oklab 感知均匀颜色空间，L 值与人眼感知亮度线性对应，所以同 L=60% 的红（0°）和蓝（240°）视觉亮度基本相同。HSL 的 L 是数学平均（max+min)/2，未考虑人眼对不同波长光的敏感度差异（视锥细胞对黄绿最敏感、对蓝紫最不敏感），所以同 L 值下黄色看起来远比蓝色亮。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>oklch vs hsl 感知均匀对比 + color-mix 混色 + light-dark 双主题卡片 + 相对颜色状态推导 + 10 级色板自动生成：<a href="./../../examples/css/14-modern-colors/index-01-modern-colors.html">examples/css/14-modern-colors/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 25 话《滚动驱动动画》——<code>animation-timeline: scroll()</code> 与 <code>view()</code>，纯 CSS 实现滚动视差与进出场动画，告别 JavaScript 滚动监听。</p>',25)])])}const g=e(c,[["render",i]]);export{k as __pageData,g as default};
